\coordinate (A) at (0,2.5);
\coordinate (B) at (3.2,2.5);
\coordinate (C) at (3.2,0);
\coordinate (D) at (0,0);
\draw (A) -- (B) node[midway, above] {$5$};
\draw (B) -- (C) node[midway, right] {$8$};
\draw (C) -- (D) node[midway, below] {$4$};
\draw (D) -- (A) node[midway, left] {$6$};
\draw (A) -- (C) node[midway, fill=white, inner sep=1pt] {$9$};
\fill (A) circle (2.5pt) node[above left] {$A$};
